ALTER TABLE "nodes" ADD COLUMN "system_kind" text;--> statement-breakpoint
UPDATE "nodes" SET "system_kind" = 'phone_backup' WHERE "kind" = 'folder' AND "id" IN (SELECT p."parent_id" FROM "nodes" p WHERE p."id" IN (SELECT "folder_id" FROM "phone_backups" WHERE "folder_id" IS NOT NULL) AND p."parent_id" IS NOT NULL);--> statement-breakpoint
UPDATE "nodes" SET "system_kind" = 'partner' WHERE "kind" = 'folder' AND "name" LIKE 'From %' AND "vault_id" IS NULL AND "parent_id" IN (SELECT "id" FROM "nodes" WHERE "kind" = 'folder' AND "parent_id" IS NULL AND lower("name") = 'photos') AND "id" IN (SELECT DISTINCT "parent_id" FROM "nodes" WHERE "kind" = 'file' AND "parent_id" IS NOT NULL);--> statement-breakpoint
UPDATE "nodes" SET "system_kind" = 'camera' WHERE "kind" = 'folder' AND "parent_id" IS NULL AND "vault_id" IS NULL AND lower("name") = 'camera' AND "id" IN (SELECT "parent_id" FROM "nodes" WHERE "kind" = 'folder' AND "name" ~ '^(19|20)[0-9][0-9]$' AND "parent_id" IS NOT NULL);
